const usMapSvg=await fetch('./us-map.svg').then(r=>r.text());
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),pct=v=>v.toLocaleString('en-US',{maximumFractionDigits:1})+'%';
let route='epidemiology',dimension='age',type='all',epiProfile='Age',epiTreatment='Age',careDim='Age',insulinType='type2',insulinDim='Age',deviceView='cgm',persona='insulin',stage=0,theme='food',company='dexcom',search='',category='all',selectedState=null;const selected=new Set();
const typeNames={all:'All types',t1:'Type 1',t2:'Type 2',gest:'Gestational',pre:'Prediabetes'};
const stateRates={AK:8.3,AL:13.7,AR:13,AZ:9.8,CA:10.5,CO:8,CT:8.3,DC:8.2,DE:11.1,FL:10,GA:11.4,HI:9.5,IA:9.8,ID:8.7,IL:10.8,IN:11.5,KS:10.3,KY:null,LA:14.5,MA:8.5,MD:10.8,ME:8.9,MI:10.7,MN:9.3,MO:10.6,MS:14.7,MT:7.9,NC:10.8,ND:8.8,NE:9.6,NH:7.9,NJ:9.1,NM:10.7,NV:10.6,NY:9.3,OH:11.3,OK:11.1,OR:9.5,PA:null,RI:10,SC:12.6,SD:10.5,TN:12.7,TX:12,UT:8,VA:10.3,VT:7.7,WA:8.6,WI:9.4,WV:15,WY:9.4};
const stateNames={AK:'Alaska',AL:'Alabama',AR:'Arkansas',AZ:'Arizona',CA:'California',CO:'Colorado',CT:'Connecticut',DC:'District of Columbia',DE:'Delaware',FL:'Florida',GA:'Georgia',HI:'Hawaii',IA:'Iowa',ID:'Idaho',IL:'Illinois',IN:'Indiana',KS:'Kansas',KY:'Kentucky',LA:'Louisiana',MA:'Massachusetts',MD:'Maryland',ME:'Maine',MI:'Michigan',MN:'Minnesota',MO:'Missouri',MS:'Mississippi',MT:'Montana',NC:'North Carolina',ND:'North Dakota',NE:'Nebraska',NH:'New Hampshire',NJ:'New Jersey',NM:'New Mexico',NV:'Nevada',NY:'New York',OH:'Ohio',OK:'Oklahoma',OR:'Oregon',PA:'Pennsylvania',RI:'Rhode Island',SC:'South Carolina',SD:'South Dakota',TN:'Tennessee',TX:'Texas',UT:'Utah',VA:'Virginia',VT:'Vermont',WA:'Washington',WI:'Wisconsin',WV:'West Virginia',WY:'Wyoming'};
