const nationalStateTrend=[[2000,6],[2001,6.3],[2002,6.7],[2003,7],[2004,6.9],[2005,7.3],[2006,7.4],[2007,7.8],[2008,7.9],[2009,8],[2010,8.3],[2011,9],[2012,9],[2013,9],[2014,9.2],[2015,9.1],[2016,9.5],[2017,9.4],[2018,9.8],[2019,9.4],[2020,9.4],[2021,9.7],[2022,9.7],[2023,10.3]];
