function source(id,label){return `<button class="source" data-source="${id}">${esc(label||sources[id].title)} ↗</button>`}
function foot(id,label){return `<div class="source-row">${source(id,label)}</div>`}
function link(r,label){return `<button class="linkbutton" data-go="${r}">${label} →</button>`}
function head(title,sub='',extra=''){return `<div class="pagehead"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>`}
function kpi(label,value,note,id){return `<article class="kpi"><span class="kpi-label">${label}</span><button class="info" data-source="${id}" aria-label="Source: ${label}">ⓘ</button><strong>${value}</strong><p>${note}</p></article>`}
function types(){return `<div class="type-tabs" aria-label="Diabetes type">${Object.entries(typeNames).map(([id,label])=>`<button data-type="${id}" class="${type===id?'active':''}" aria-pressed="${type===id}">${label}</button>`).join('')}</div>`}
function hbars(rows,max=100,color='var(--blue)'){return rows.map(([label,v,ci])=>`<div class="hrow"><div class="hmeta"><span>${esc(label)}</span><strong>${pct(v)}</strong></div><div class="track"><div class="fill" style="width:${v/max*100}%;background:${color}"></div></div>${ci?`<small class="caption">95% CI: ${ci}%</small>`:''}</div>`).join('')}
function panel(title,body,id){return `<article class="panel"><div class="panelhead"><h2>${title}</h2></div>${body}${id?foot(id):''}</article>`}
function profileBars(d){return `<div class="profile-bars">${d.rows.map(([label,v])=>`<div class="profile-row"><span>${esc(label)}</span><div><i style="width:${v/d.max*100}%"></i></div><b>${pct(v)}</b></div>`).join('')}</div>`}
function sexRings(){const d=demographics.sex;return `<div class="sex-rings" role="img" aria-label="${esc(d.rows.map(r=>r[0]+': '+pct(r[1])).join('; '))}">${d.rows.map(([label,v])=>`<div><i style="--value:${v}"><span>${pct(v)}</span></i><b>${label}</b></div>`).join('')}</div>`}
function demographic(){const d=typeData.type2,dimensions=['Sex','Age','Race','Education','Income'];const colors={oral:'#5858d8',insulin:'#159c91',injectable:'#de8b54'};const row=(label,prevalence,oral,insulin,injectable)=>`<div class="continuum-row"><b>${esc(label)}</b><strong style="text-align:center;font-size:12px">${prevalence.toFixed(1)}%</strong><div class="treatment-cell">${[['Oral',oral,colors.oral],['Insulin',insulin,colors.insulin],['Other injectable',injectable,colors.injectable]].map(([name,value,color])=>`<div title="${name}: ${value.toFixed(1)}%"><i><span style="width:${value}%;background:${color}"></span></i><strong>${value.toFixed(1)}%</strong></div>`).join('')}</div></div>`;return `<article class="panel continuum-dashboard"><div class="panelhead"><div><h2>Who has type 2 diabetes—and how is it treated?</h2><p>Every demographic group appears once; treatment measures sit beside disease burden</p></div><span class="pill purple">NHIS 2025 · U.S.</span></div><div class="continuum-legend"><span>Type 2 prevalence <small>within the full population group</small></span><span><i style="background:${colors.oral}"></i>Oral medication</span><span><i style="background:${colors.insulin}"></i>Insulin</span><span><i style="background:${colors.injectable}"></i>Other injectable</span><em>Treatment measures are among adults reporting type 2; categories can overlap.</em></div><div class="continuum-grid">${dimensions.map(dim=>{const prevalence=d.prevalence[dim],oral=d.treatment.DIBPILL_A[dim],insulin=d.treatment.DIBINS_A[dim],injectable=d.treatment.DIBGLP_A[dim];return `<section class="continuum-card ${dim==='Race'?'wide':''}"><h3>${dim==='Race'?'Race & ethnicity':dim}</h3><div class="continuum-head"><span>Group</span><span style="text-align:center">Has type 2</span><span>Uses treatment</span></div>${prevalence.map(([label,value],i)=>row(label,value,oral[i]?.[1]??0,insulin[i]?.[1]??0,injectable[i]?.[1]??0)).join('')}</section>`}).join('')}</div><p class="continuum-note">This view is designed for pattern-finding, not subtraction: prevalence and treatment bars use different denominators. Education is shown in four groups—less than high school, high school/GED, some college/associate degree, and bachelor’s or higher.</p></article>`}
function adoption(){return panel('Technology use is expanding',`<p class="sub">CGM · type 2 using insulin · Medicare Advantage</p><div class="adoption"><div class="metric-inline">1.4%<small style="display:block">January 2021</small></div><span class="arrow">→</span><div class="metric-inline" style="color:var(--blue)">17.2%<small style="display:block">December 2023</small></div></div><p class="caption">Study endpoints, not a complete monthly series or an estimate for all US patients.</p>${link('industry/products','Explore devices')}`,'adoption')}
function epiTabs(kind,current){const labels=kind==='profile'?['Age','Sex','Education','Income','Race']:['Age','Sex','Education','Income','Race'];return `<div class="mini-tabs epi-tabs">${labels.map(label=>`<button data-epi-${kind}="${label}" class="${current===label?'active':''}">${label==='Race'?'Race & ethnicity':label}</button>`).join('')}</div>`}
function epiTrend(data){const values=data.trend.map(d=>d[1]),min=Math.max(0,Math.min(...values)-.3),max=Math.max(...values)+.3,w=720,h=230,p=35;const x=i=>p+i*(w-p*2)/(values.length-1),y=v=>h-p-(v-min)*(h-p*2)/(max-min);const points=data.trend.map((d,i)=>`${x(i)},${y(d[1])}`).join(' ');const slope=(values.at(-1)-values[0])/(values.length-1);return `<article class="panel epi-trend"><div class="panelhead"><div><h2>Prevalence trend</h2><p>NHIS 2019–2025</p></div><span class="pill purple">${slope>.025?'Increasing':slope<-.025?'Decreasing':'Approximately stable'}</span></div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${data.trend.map(d=>d[0]+': '+d[1].toFixed(2)+'%').join('; ')}"><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" class="epi-axis"/><polyline points="${points}" class="epi-line"/>${data.trend.map((d,i)=>`<g><circle cx="${x(i)}" cy="${y(d[1])}" r="5"/><text x="${x(i)}" y="${y(d[1])-12}" class="epi-value">${d[1].toFixed(2)}%</text><text x="${x(i)}" y="${h-10}" class="epi-year">${d[0]}</text></g>`).join('')}</svg><p class="caption">Annual weighted estimates from NHIS public-use files. The line describes observed direction; it is not a forecast.</p></article>`}
function epiProfileChart(data){const rows=data.prevalence[epiProfile],max=Math.max(...rows.map(r=>r[1]))*1.12;return `<article class="panel"><div class="panelhead"><div><h2>Population profile</h2><p>Prevalence within each group</p></div><span class="pill purple">${typeNames[type]}</span></div>${epiTabs('profile',epiProfile)}<div class="epi-bars">${rows.map(([label,v])=>`<div class="epi-row"><span>${label}</span><div><i style="width:${v/max*100}%"></i></div><strong>${v.toFixed(1)}%</strong></div>`).join('')}</div><p class="caption">Weighted NHIS 2025 estimates. Category names reproduce the public-use survey groups.</p></article>`}
function epiTreatmentChart(data){const labels={DIBPILL_A:'Oral medication',DIBINS_A:'Insulin',DIBGLP_A:'Non-insulin injectable'},colors={DIBPILL_A:'#6558d3',DIBINS_A:'#159c91',DIBGLP_A:'#de8b54'};const keys=Object.keys(labels),rowLabels=data.treatment.DIBPILL_A[epiTreatment].map(r=>r[0]);return `<article class="panel epi-treatment"><div class="panelhead"><div><h2>Reported treatment use</h2><p>Among adults reporting ${typeNames[type].toLowerCase()} diabetes</p></div></div>${epiTabs('treatment',epiTreatment)}<div class="epi-legend">${keys.map(k=>`<span><i style="background:${colors[k]}"></i>${labels[k]}</span>`).join('')}</div><div class="epi-treatment-rows">${rowLabels.map((label,i)=>`<div class="epi-treatment-row"><b>${label}</b><div>${keys.map(k=>{const v=data.treatment[k][epiTreatment][i]?.[1]??0;return `<span title="${labels[k]}: ${v.toFixed(1)}%"><i style="width:${v}%;background:${colors[k]}"></i><em>${v.toFixed(1)}%</em></span>`}).join('')}</div></div>`).join('')}</div><p class="caption">Categories overlap: one person may report more than one therapy. Type is based on the respondent’s report of the type identified by a health professional.</p></article>`}
function populationOverview(){const segments=[['Diagnosed diabetes',10.8,'#6558d3','28.8m'],['Undiagnosed diabetes',4.1,'#a59dec','11.0m'],['Prediabetes',43.1,'#159c91','115.2m'],['No diabetes or prediabetes',42.0,'#dfe2e8','≈112.1m']];return `<article class="panel population-overview"><div class="panelhead"><div><h2>U.S. adults across the diabetes risk spectrum</h2><p>Adults 18+ · 2023</p></div><strong class="population-callout">58%<small>diabetes or prediabetes</small></strong></div><div class="population-chart" role="img" aria-label="10.8% diagnosed diabetes; 4.1% undiagnosed diabetes; 43.1% prediabetes; 42.0% no diabetes or prediabetes"><div class="population-bar">${segments.map(([label,value,color])=>`<span style="width:${value}%;background:${color}" title="${label}: ${value}%"></span>`).join('')}</div><div class="population-labels">${segments.map(([label,value,color,count])=>`<div><i style="background:${color}"></i><b>${value.toFixed(1)}%</b><span>${label}</span><small>${count} adults</small></div>`).join('')}</div></div><p class="caption">The four risk-spectrum groups total 100% of U.S. adults. The diabetes-type figures are reference measures with their populations written directly beside each value.</p>${foot('cdc','CDC · National Diabetes Statistics Report')}</article>`}
function gestationalProfile() {
  const groups = [
    ['Maternal age · U.S., 2023', [['Under 20',2.47],['20–24',4.63],['25–29',7.11],['30–34',9.19],['35–39',11.91],['40–54',14.97]]],
    ['Five highest state rates · U.S., 2020', [['Alaska',12.6],['Washington',10.9],['Oregon',10.1],['New Jersey',9.6],['Arizona',9.5]]],
    ['Education · Virginia', [['Less than high school',7],['High school',18.1],['Beyond high school',9.9]]],
    ['Annual income · Virginia', [['Under $20,000',12.6],['$20,001–57,000',12.7],['Over $57,000',8.8]]]
    ,['Insurance coverage · Virginia', [['Medicaid',18.9],['Private insurance',9.4],['Other insurance',14.7],['Uninsured',8.2]]]
    ,['Primary payer for delivery · U.S., 2018', [['Medicaid',6.5,41.2],['Private insurance',7,52.1],['Self-pay',5,3.2],['Other payer',6,3.5]]]
  ];
  return `<article class="panel gestational-profile"><div class="panelhead"><div><h2>Gestational diabetes</h2><p>Reported among women with a live birth</p></div><strong class="gestational-total">8.3%<small>U.S. live births · 2023</small></strong></div><table style="width:100%;border-collapse:collapse;text-align:left;font-size:13px"><caption style="text-align:left;padding:8px 0">Gestational diabetes within each group</caption><thead><tr><th scope="col">Population group</th><th scope="col" style="text-align:right">Cases per 100 in group</th><th scope="col" style="text-align:right">Estimated share of cases</th></tr></thead>${groups.map(([title,rows])=>`<tbody><tr><th scope="rowgroup" colspan="3" style="background:#f4f4fa;padding:8px">${esc(title)}</th></tr>${rows.map(([label,value,share])=>`<tr><th scope="row" style="padding:4px 8px;font-weight:400">${esc(label)}</th><td style="text-align:right;padding:4px 8px">${value.toFixed(1)}</td><td style="text-align:right;padding:4px 8px">${share == null ? "—" : share.toFixed(1)+"%"}</td></tr>`).join('')}</tbody>`).join('')}</table></article>`;
}
function stateColor(v){return v==null?'#ececf1':v<8.5?'#e6f4f2':v<10?'#a9ddd7':v<11.5?'#61bdb4':v<13?'#2c9188':'#12655f'}
function mapMarkup(){return usMapSvg.replace('<svg ','<svg class="real-us-map" role="group" aria-label="Interactive United States diabetes prevalence map" ').replace(/<path id="([A-Z]{2})"/g,(m,id)=>{const v=stateRates[id];return `<path id="${id}" data-state="${id}" tabindex="0" aria-label="${stateNames[id]||id}: ${v==null?'No 2023 data':v.toFixed(1)+'%'}" class="map-state ${selectedState===id?'selected':''}" style="fill:${stateColor(v)}"`})}
function stateRank(id){const ranked=Object.entries(stateRates).filter(([,v])=>v!=null).sort((a,b)=>b[1]-a[1]),index=ranked.findIndex(([key])=>key===id);return index<0?null:[index+1,ranked.length]}
function stateMap(){const value=selectedState?stateRates[selectedState]:10.3,delta=selectedState&&value!=null?value-10.3:null,rank=selectedState?stateRank(selectedState):null;return `<article class="panel state-map-panel"><div class="panelhead"><div><h2>Diagnosed diabetes across the U.S.</h2><p>Select a state to update the state-level analysis</p></div><div class="geo-filter"><button data-state-all class="${selectedState?'':'active'}">All states</button>${selectedState?`<button data-state-all>× Clear ${stateNames[selectedState]}</button>`:''}</div></div><label class="mobile-state-picker">Choose a state<select id="state-select"><option value="">All states</option>${Object.entries(stateNames).sort((a,b)=>a[1].localeCompare(b[1])).map(([id,name])=>`<option value="${id}" ${selectedState===id?'selected':''}>${name}</option>`).join('')}</select></label><div class="map-layout"><div class="real-map-wrap">${mapMarkup()}<div id="map-tooltip" class="map-tooltip" hidden></div></div><div class="map-selection"><span>${selectedState?'Selected state':'All states'}</span><b>${selectedState?stateNames[selectedState]:'United States'}</b><strong>${value==null?'No data':value.toFixed(1)+'%'}</strong><small>${selectedState?(delta==null?'2023 estimate unavailable':`${delta>=0?'+':''}${delta.toFixed(1)} pp vs. U.S. median`):'2023 median of states'}</small>${rank?`<em>Rank #${rank[0]} of ${rank[1]}</em>`:''}</div></div><div class="map-legend"><span>Lower</span>${[8,9.2,10.5,12,14].map(v=>`<i style="background:${stateColor(v)}"></i>`).join('')}<span>Higher</span><b>Age-adjusted · adults 18+ · 2023</b></div></article>`}
function geoSeries(id){return stateSeries.filter(d=>d.state===(id||'All')&&d.estimate).map(d=>[+d.year,+d.estimate]).sort((a,b)=>a[0]-b[0])}
function nationalTrend(){const data=geoSeries(selectedState),national=geoSeries(null),w=700,h=250,p=36,all=[...data,...(selectedState?national:[])],min=Math.max(0,Math.min(...all.map(d=>d[1]))-.6),max=Math.max(...all.map(d=>d[1]))+.6,x=yr=>p+(yr-2000)*(w-p*2)/23,y=v=>h-p-(v-min)*(h-p*2)/(max-min),points=rows=>rows.map(d=>`${x(d[0])},${y(d[1])}`).join(' '),first=data[0],last=data.at(-1),change=first&&last?last[1]-first[1]:null;return `<article class="panel national-trend"><div class="panelhead"><div><h2>${selectedState?stateNames[selectedState]:'All states'} over time</h2><p>Age-adjusted diagnosed diabetes · 2000–2024</p></div><strong>${change==null?'—':(change>=0?'+':'')+change.toFixed(1)+' pp'}</strong></div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${selectedState?stateNames[selectedState]:'State median'} diabetes prevalence trend">${selectedState?`<polyline points="${points(national)}" class="epi-line comparison-line"/>`:''}<polyline points="${points(data)}" class="epi-line"/><line x1="${x(2011)}" y1="${p}" x2="${x(2011)}" y2="${h-p}" class="method-break"/>${data.map((d,i)=>i===0||d[0]===2011||i===data.length-1?`<g><circle cx="${x(d[0])}" cy="${y(d[1])}" r="5"/><text x="${x(d[0])}" y="${y(d[1])-12}" class="epi-value">${d[1].toFixed(1)}%</text><text x="${x(d[0])}" y="${h-10}" class="epi-year">${d[0]}</text></g>`:'').join('')}<text x="${x(2011)+7}" y="${p+10}" class="method-label">BRFSS change</text></svg>${selectedState?'<div class="trend-legend"><span><i></i>Selected state</span><span><i class="national"></i>U.S. state median</span></div>':''}</article>`}
function stateSpread(){const ranked=Object.entries(stateRates).filter(([,v])=>v!=null).sort((a,b)=>b[1]-a[1]);if(selectedState)return '';const shown=[...ranked.slice(0,5),...ranked.slice(-5).reverse()];return `<article class="panel state-spread"><div class="panelhead"><div><h2>Where prevalence is highest and lowest</h2><p>Five highest and five lowest states · 2023</p></div></div><div class="rank-bars">${shown.map(([id,v],i)=>`<button data-state="${id}" class="rank-row ${i===5?'rank-break':''}"><span>${stateNames[id]}</span><div><i style="width:${v/16*100}%;background:${stateColor(v)}"></i></div><b>${v.toFixed(1)}%</b></button>`).join('')}</div></article>`}
function geographyDashboard(){return `<section class="geography-dashboard">${stateMap()}<div class="grid-two geo-charts ${selectedState?'single':''}">${nationalTrend()}${stateSpread()}</div></section>`}
function payerBar(){const rows=[['Medicare',41,'#5858d8'],['Private insurance',32,'#7f7fe3'],['Medicaid',17.2,'#308d87'],['Out of pocket',6.2,'#cf8950'],['Other',3.5,'#b9bdc9']];return `<div class="payer-bar" role="img" aria-label="${rows.map(r=>r[0]+': '+r[1]+'%').join('; ')}">${rows.map(([label,v,color])=>`<i style="width:${v}%;background:${color}" title="${label}: ${v}%"></i>`).join('')}</div><div class="payer-legend">${rows.map(([label,v,color])=>`<span><i style="background:${color}"></i><b>${v}%</b> ${label}</span>`).join('')}</div>`}
function smallTabs(attr,items,current){return `<div class="mini-tabs care-tabs">${items.map(x=>`<button data-${attr}="${x}" class="${current===x?'active':''}">${x==='Race'?'Race & ethnicity':x}</button>`).join('')}</div>`}
function compactBars(rows,max){return `<div class="compact-bars">${rows.map(([label,v])=>`<div><span>${label}</span><i><b style="width:${v/max*100}%"></b></i><strong>${v.toFixed(1)}%</strong></div>`).join('')}</div>`}
function coverageProfile(){const data={Age:[['18–44',2.5],['45–64',12.7],['65+',21.6]],Sex:[['Men',10.7],['Women',9.6]],Income:[['<125% FPL',14.9],['125–199% FPL',12.4],['200–399% FPL',10.4],['400%+ FPL',7.9]],Region:[['Northeast',9],['Midwest',10.8],['South',11.2],['West',8.6]],Race:[['White, non-Hispanic',9.5],['Black, non-Hispanic',12.9],['Asian, non-Hispanic',10.2],['Hispanic',9.8]]},rows=data[careDim],max=Math.max(...rows.map(r=>r[1]))*1.12;return `<section class="coverage-profile"><div class="section-title"><div><h3>Who receives diabetes treatment?</h3><p>Rate within each population group</p></div><span>MEPS 2021–2022</span></div>${smallTabs('care-dim',Object.keys(data),careDim)}${compactBars(rows,max)}<small>This profile and the payer shares come from the same MEPS brief, but the published brief does not cross each payer with each demographic group.</small></section>`}
function insulinProfile(){const data=typeData[insulinType].treatment.DIBINS_A,rows=data[insulinDim],max=Math.max(...rows.map(r=>r[1]))*1.08;return `<section class="insulin-profile"><div class="section-title"><div><h3>Who uses insulin?</h3><p>Reported current use among adults reporting this diabetes type</p></div><div class="segmented"><button data-insulin-type="type1" class="${insulinType==='type1'?'active':''}">Type 1</button><button data-insulin-type="type2" class="${insulinType==='type2'?'active':''}">Type 2</button></div></div>${smallTabs('insulin-dim',['Age','Sex','Education','Income','Race'],insulinDim)}${compactBars(rows,max)}<small>NHIS 2025 weighted estimates. Education has four groups here: less than high school, high school/GED, some college/associate degree, and bachelor’s or higher. Region is not included in this tabulation.</small></section>`}
function deviceProfile(){const rows=[['Average age',50.3,56.1,'years'],['Employed',59.6,30.6,'%'],['Household income ≥$75k',48.5,22.0,'%'],['Insured',99.7,95.4,'%']];return `<article class="panel technology-profile"><div class="panelhead"><div><h2>Who uses continuous glucose monitoring?</h2><p>Observed profile of CGM users compared with fingerstick users</p></div><span class="pill purple">BRFSS 2014–2020</span></div><div class="tech-legend"><span><i></i>CGM users</span><span><i></i>Fingerstick users</span></div><div class="tech-profile-grid">${rows.map(([label,cgm,smbg,unit])=>{const max=unit==='years'?70:100;return `<div class="tech-row"><b>${label}</b><div><span>CGM</span><i><em style="width:${cgm/max*100}%"></em></i><strong>${cgm.toFixed(1)}${unit}</strong></div><div><span>Fingerstick</span><i><em style="width:${smbg/max*100}%"></em></i><strong>${smbg.toFixed(1)}${unit}</strong></div></div>`}).join('')}</div><div class="technology-boundary"><strong>What this tells us</strong><p>CGM users in this study were younger, more often employed, more often in higher-income households and almost universally insured. The data describe CGM as a category—not Dexcom versus Libre, and not current market share.</p><p>Comparable national demographic profiles are not available here for individual pumps/AID systems or OTC sensors. Their product pages show eligibility and indications, not who actually adopts them.</p></div><button class="linkbutton" data-go="industry/products">See devices and product indications →</button></article>`}
function careProfile(){return `<section class="care-story"><div class="story-head"><div><h2>Payment and technology</h2><p>One spending view and one technology-user profile</p></div><span class="pill purple">U.S. · national data</span></div><article class="panel payer-panel"><div class="panelhead"><div><h2>Who pays for diabetes treatment?</h2><p>Share of treatment expenditures · adults treated for diabetes</p></div><strong>$153.2bn<small>annual spending · 2021–2022</small></strong></div>${payerBar()}</article>${deviceProfile()}</section>`}
function epidemiologyNotes(){return `<section class="methodology"><div class="panelhead"><div><h2>Sources & methodology</h2><p>Definitions, comparability and interpretation notes</p></div></div><details open><summary>Population overview</summary><p>CDC 2023 adult estimates. The four population groups are mutually exclusive. Percentages calculated from rounded counts may differ by 0.1 percentage point from separately published CDC estimates. “No diabetes or prediabetes” does not mean free of other health conditions.</p></details><details><summary>Geography and trend</summary><p>State figures are BRFSS age-adjusted prevalence of self-reported diagnosed diabetes among adults 18+. Gestational-only diabetes is excluded. The national line is the median of states, not the same measure as the national adult prevalence estimate. BRFSS methodology changed in 2011, which may affect comparisons across that boundary. Kentucky and Pennsylvania have no 2023 estimate in this dataset.</p></details><details><summary>Type and subgroup analysis</summary><p>Gestational diabetes rates use live births as the denominator. Type 1 estimates use a different published age boundary. Type-specific NHIS subgroup results are descriptive; Type 1 has a smaller sample and greater uncertainty. Treatment categories overlap.</p></details><details><summary>Gestational diabetes profile</summary><p>Age-specific U.S. rates increased across age groups. Virginia estimates showed similar rates in the two lower income bands and no consistent education gradient. Survey uncertainty limits subgroup comparisons. Age-adjusted comparisons by income and coverage require joint records.</p><p>A dash indicates a case share unavailable here. Virginia PRAMS reports rates by coverage without weighted case totals. For U.S. deliveries in 2018, estimated shares weight each published gestational diabetes rate by its payer’s share of births and divide by the sum across payers. Inputs are rounded and exclude unknown statuses. <a href="https://www.medicaid.gov/medicaid/quality-of-care/downloads/mih-beneficiary-profile.pdf">CMS maternal and infant health profile</a>.</p><p>State rankings use rates per 100 live births in <a href="https://www.cdc.gov/nchs/data/nvsr/nvsr71/nvsr71-03.pdf">NCHS Table 4 (2020)</a>. Education, income and insurance coverage use separate weighted estimates from <a href="https://www.vdh.virginia.gov/content/uploads/sites/67/2025/01/Gestational-Diabetes-Data.pdf">Virginia PRAMS</a>.</p></details><div class="method-sources">${['cdc','births2023','state','nchs','report'].map(id=>source(id)).join('')}</div></section>`}
function typeDiagnosis(){const data=typeData[type==='t1'?'type1':'type2'],change=data.trend.at(-1)[1]-data.trend[0][1];return `<div class="kpis">${kpi('Adult prevalence',data.adult_prevalence.toFixed(2)+'<small>%</small>','Adults 18+ · NHIS 2025','report')}${kpi('Estimated adults',(data.population/1e6).toFixed(2)+'<small>m</small>','Weighted population estimate','report')}${kpi('2019–2025 change',(change>=0?'+':'')+change.toFixed(2)+' <small>pp</small>','Percentage-point change','report')}${kpi('Survey respondents',data.n.toLocaleString('en-US'),'Unweighted sample reporting type','report')}</div><div class="epi-grid">${epiTrend(data)}${epiProfileChart(data)}</div>${epiTreatmentChart(data)}<div class="epi-method"><strong>Interpretation boundary</strong><p>These estimates use self-reported diabetes type in NHIS. Type 1 has a much smaller sample and substantially less precision. Subgroup percentages should be treated as descriptive until confidence intervals and reliability flags are added.</p></div>`}
function epidemiology(){const focus={gest:['8.3%','of U.S. live births had gestational diabetes recorded in 2023.','births2023'],pre:['115.2 million','U.S. adults age 18+ with prediabetes, defined among people without diabetes.','cdc']};const overview=`${populationOverview()}${gestationalProfile()}${geographyDashboard()}${demographic()}${careProfile()}`;let body=type==='all'?overview:type==='gest'?gestationalProfile():(type==='t1'||type==='t2')?typeDiagnosis():`<div class="type-focus"><div><h2>${typeNames[type]}</h2><p>${focus[type][1]}</p>${foot(focus[type][2])}</div><strong>${focus[type][0]}</strong></div><p class="contextline">A complete type-specific diagnostic panel is currently available for Type 1 and Type 2.</p>`;return `<section class="epidemiology-page">`+head('Epidemiology','Diabetes in the United States',types())+body+`${epidemiologyNotes()}</section>`}
function healthcare(){return head('Healthcare system','Access, coverage, education and the cost of care.')+`<div class="kpis">${kpi('Economic burden','$412.9 <small>bn</small>','Diagnosed diabetes · US · 2022','cost')}${kpi('Direct medical costs','$306.6 <small>bn</small>','Part of total burden · 2022','cost')}${kpi('Received diabetes education','52<small>%</small>','Study published 2022 · CDC summary 2024','education')}${kpi('No usual place for care','4.8<small>%</small>','Diagnosed adults · NHANES 2021–2023','report')}</div><div class="grid-two">${panel('CGM coverage through Medicare',`<p class="big-note">Coverage may apply to people with diabetes who use insulin or have a history of hypoglycemia, when prescribed and other requirements are met.</p><p class="caption">Eligibility, training and supplier requirements apply. This is not a universal coverage guarantee.</p>${link('industry/products','Connect coverage to devices')}`,'medicare')}${panel('Education and support',`<p class="big-note">Learning how to manage diabetes is part of the care system. Participation varies across populations and access conditions.</p><p class="caption">The CDC summary reports lower education participation among uninsured people, rural residents and people with less education.</p>${link('patients/routine','See the patient perspective')}`,'education')}</div><div class="industry-nav"><button data-go="patients/journey"><span>◉</span><div><strong>Patients</strong><small>Receiving and sustaining care</small></div></button><button data-go="caregivers/journey"><span>◎</span><div><strong>Caregivers</strong><small>Coordinating support</small></div></button><button data-go="industry/market"><span>↗</span><div><strong>Industry & market</strong><small>Products and adoption</small></div></button></div>`}
function patientProfile(){return head('Patient profile','Different conditions, treatment contexts and everyday tasks.')+`<div class="grid-main">${demographic()}${panel('Explore the experience',personas.filter(p=>p.audience==='patients').map(p=>`<button class="type-row" data-persona="${p.id}"><span><b>${p.label}</b><small>${p.task}</small></span><strong>→</strong></button>`).join(''))}</div><div class="grid-two">${adoption()}${panel('Care has an emotional dimension',`<div class="metric-inline">24.3% <small>moderate diabetes distress</small></div><p class="big-note">Emotional burden is part of the experience of living with diabetes.</p>${link('patients/routine','Explore care routines')}`,'distress')}</div>`}
function caregiverProfile(){return head('Caregiver profile','Support, shared responsibilities and autonomy.')+`<div class="family-overview"><div class="family-orbit"><div class="orbit-center">Person with<br><strong>diabetes</strong></div><span class="orbit-person one">Family</span><span class="orbit-person two">Caregivers</span><span class="orbit-person three">Care team</span><span class="orbit-person four">Support network</span></div><div><h2>Care extends to the people around the patient.</h2><p>Caregiver involvement changes with age, independence, preferences and support needs.</p>${source('family')}<div class="family-actions"><button data-go="caregivers/personas">Explore personas →</button><button data-go="caregivers/journey">Explore the journey →</button></div></div></div><div class="grid-two">${personas.filter(p=>p.audience==='caregivers').map(p=>panel(p.label,`<p class="big-note">${p.context}</p><p class="caption">${p.task}</p><button class="linkbutton" data-persona="${p.id}">Explore this persona →</button>`,'family')).join('')}</div><p class="caption">No national caregiver count or caregiver-burden estimate is available in this edition. Patient estimates are not transferred to caregivers.</p>`}
function personaPage(audience){let list=personas.filter(p=>p.audience===audience);if(!list.some(p=>p.id===persona))persona=list[0].id;const p=list.find(x=>x.id===persona);return head('Personas','Evidence-informed use profiles. Needs remain research hypotheses, not interview findings.')+`<div class="persona-strip">${list.map((x,i)=>`<button data-persona-select="${x.id}" class="${x.id===persona?'active':''}"><span class="persona-symbol">${['◉','▤','◌','◐'][i%4]}</span><strong>${x.label}</strong><small>${x.tags.join(' · ')}</small></button>`).join('')}</div><div class="persona-detail"><div class="persona-core"><span class="pill purple">${typeNames[p.type]}</span><h2>${p.label}</h2><p>${p.context}</p>${foot(p.source,'Evidence behind this context')}</div><div class="persona-fields"><div><span>Core task</span><p>${p.task}</p></div><div><span>To investigate</span><p>${p.friction}</p></div><div><span>Related tools</span><p>${p.device}</p></div></div></div><div class="grid-three">${panel('Journey',`<p class="big-note">Follow this profile into a care moment.</p><button class="linkbutton" id="persona-journey">Explore the journey →</button>`)}${panel('Care routine',`<p class="big-note">Understand the ongoing work and questions.</p>${link(audience+'/routine','Explore the routine')}`)}${panel('Products',`<p class="big-note">Review tools and their stated indications.</p>${link('industry/products','Explore products')}`)}</div>`}
const moments=['Recognize & confirm','Learn & begin','Integrate into daily life','Reassess & sustain'];
const patientStages=[['What is happening to me?','Understand signs, evaluation and the diagnosis.','Primary care, tests and conversations with professionals.','27.6% of adults with diabetes are undiagnosed.','cdc','How does a person find a path from concern to evaluation?','tech'],['What changes now?','Understand the care plan and learn how to use indicated treatments and tools.','Care team, education, pharmacy and support resources.','52% reported receiving diabetes education in the study summarized by CDC.','education','Which instructions make sense, and where does learning break down?','food'],['How does this fit my life?','Coordinate monitoring, meals, activity and follow-up.','Devices, apps, appointments and everyday routines.','CGM adoption increased in a studied subgroup of type 2 insulin users in Medicare Advantage.','adoption','Which tasks, costs or interruptions make daily care harder?','exercise'],['How do I keep going?','Revisit the care plan and address practical and emotional burden.','Follow-up, professional support and communities.','Adjusted diabetes distress prevalence was 24.3% moderate and 6.6% severe in NHIS 2021.','distress','When does care burden create a need for additional support?','burnout']];
const caregiverStages=[['How do we understand what changed?','Learn about the diagnosis and agree on desired involvement.','The person with diabetes, the care team and accessible information.','CDC guidance emphasizes listening and learning about individual needs.','family','What does each caregiver need to understand first?','tech'],['How do we share responsibilities?','Coordinate learning, communication and agreed tasks.','Home, education, appointments and school when relevant.','CDC describes greater day-to-day involvement for younger and newly diagnosed children.','family','Where does information get lost between people sharing care?','food'],['How do we support autonomy?','Fit support around preferences and everyday life.','Shared routines, agreed communication and appointments when desired.','CDC recommends asking how to help and recognizing that preferences can change.','family','When does help feel useful, and when does it feel intrusive?','exercise'],['How does support change over time?','Revisit responsibilities and changing support needs.','Family, the care team and support networks.','Support needs are individual and may change over time.','family','What happens during transitions toward more or less independence?','burnout']];
function journey(audience){const [q,task,touch,evidence,id,research,topic]=(audience==='patients'?patientStages:caregiverStages)[stage];return head('Journey','A secondary-source model, not a validated interview-based sequence.')+`<div class="journey-track">${moments.map((m,i)=>`<button data-stage="${i}" class="${stage===i?'active':''}"><span>${i+1}</span><strong>${m}</strong></button>`).join('')}</div><div class="journey-focus"><div><span class="pill purple">${audience==='patients'?'Patient':'Caregiver'} perspective</span><h2>${q}</h2><p>${task}</p></div><div><span class="sub">Touchpoints</span><p>${touch}</p></div></div><div class="grid-three">${panel('What the evidence says',`<p class="big-note">${evidence}</p><p class="caption">${audience==='caregivers'?'Guidance synthesis, not a caregiver prevalence estimate.':'The source population is not restricted to this journey moment.'}</p>`,id)}${panel('What to investigate',`<p class="big-note">${research}</p><span class="pill purple">Research hypothesis</span>`)}${panel('Related questions',`<p class="big-note">Explore the information people may need in this context.</p><button class="linkbutton" data-topic="${topic}" data-target="${audience}/questions">Explore questions →</button>`)}</div><div class="connect"><span>View the same moment from another perspective.</span>${link((audience==='patients'?'caregivers':'patients')+'/journey','Switch perspective')}</div>`}
function routine(audience){if(audience==='caregivers')return head('Care routine','The work of supporting another person, with preferences and autonomy in view.')+`<div class="grid-two">${[['Learn together','Understand the agreed care plan and how to support it.'],['Coordinate tasks','Explore how home, school and other caregivers share responsibilities.'],['Communicate','Agree on what information should be shared, with whom and when.'],['Review support','Revisit roles as needs and independence change.']].map(([t,b])=>panel(t,`<p class="big-note">${b}</p><p class="caption">Editorial synthesis and research topics, not measured caregiver behavior.</p>`,'family')).join('')}</div>${link('caregivers/questions','Explore caregiver questions')}`;return head('Care routine','Observed behaviors, outcomes and the ongoing work of care.')+`<div class="kpis">${kpi('Leisure-time physical activity','36.4<small>%</small>','At least 150 min/week · diagnosed adults','report')}${kpi('Managing or losing weight','51.6<small>%</small>','Reported action to lower disease risk','report')}${kpi('Current smoking','15.2<small>%</small>','Self-reported · diagnosed adults','report')}${kpi('A1C above 9%','19.5<small>%</small>','Laboratory measure · diagnosed adults','report')}</div><div class="grid-two">${panel('Emotional burden',hbars([['No distress',49.3],['Mild',19.9],['Moderate',24.3],['Severe',6.6]])+'<p class="caption">Adjusted estimates · NHIS 2021. Distress is not a depression diagnosis.</p>','distress')}${adoption()}</div><div class="connect"><span>Connect routine tasks to the patient journey.</span>${link('patients/journey','Explore the journey')}</div>`}
function questions(audience){const t=themes.find(x=>x.id===theme);const labels=audience==='caregivers'?['How can I help without taking over?','What should we learn together?','How do we coordinate care with others?']:audience==='patients'?['What do these readings mean?','How can I fit care into daily life?','Where can I find trustworthy support?']:['What is the difference between type 1 and type 2?','What can a glucose sensor tell someone?','What are people trying to understand about food and blood sugar?'];return head(audience==='public'?'What people want to know':'Questions',audience==='public'?'Public information needs, search topics and online voices.':'Questions to investigate within this audience’s experience.')+`<div class="grid-three">${labels.map(q=>panel(q,'<p class="caption">Editorial research question, not a measured search trend or a verbatim patient quote.</p>')).join('')}</div><div class="chips" style="margin-bottom:20px">${themes.map(x=>`<button data-theme="${x.id}" class="${theme===x.id?'active':''}">${x.name}</button>`).join('')}</div><div class="grid-main">${panel(t.name,`<p class="big-note">${t.description}</p>${t.queries.map(q=>`<div class="query-row"><span>${q}</span><a href="https://trends.google.com/trends/explore?geo=US&date=today%205-y&q=${encodeURIComponent(q)}" target="_blank" rel="noopener">Google Trends ↗</a><a href="https://www.youtube.com/results?search_query=${encodeURIComponent(q)}" target="_blank" rel="noopener">YouTube ↗</a></div>`).join('')}<p class="caption">Prepared US queries, last 5 years. No search series or social metrics have been imported. No volume or trend ranking is implied.</p>`)}${panel('Related voices',`<p class="big-note">${creators.find(c=>c.id===t.creator).name}</p><p class="caption">${creators.find(c=>c.id===t.creator).profile}</p><button class="linkbutton" data-creator="${t.creator}">View creator profile →</button><div class="section-gap">${link('public/influencers','Explore all influencers')}</div>`)}</div><article class="panel"><div class="panelhead"><h2>Public content examples</h2><span class="pill purple">Editorial sample</span></div>${publicContent.filter(c=>c.topic===theme).map(c=>`<div class="signal"><div><p><a href="${c.url}" target="_blank" rel="noopener">${c.title} ↗</a></p><small>${c.creator} · ${c.format}</small></div></div>`).join('')||'<p class="caption">No individual item cataloged for this theme in this edition.</p>'}</article>`}
function influencers(){return head('Influencers','Public profiles, topics and formats. Not a reach or credibility ranking.')+`<div class="creator-grid">${creators.map(c=>`<article class="creator-card"><div class="creator-mini"><div class="avatar">${c.initials}</div><div><h2>${c.name}</h2><p>${c.brand}</p></div></div><span class="pill purple">${c.type}</span><p>${c.profile}</p><div class="tags">${c.themes.map(t=>`<span class="tag">${t}</span>`).join('')}</div><dl><dt>Formats</dt><dd>${c.format}</dd><dt>Reach / engagement</dt><dd>Not collected</dd><dt>Commercial relationships</dt><dd>Not audited</dd></dl><button class="linkbutton" data-creator="${c.id}">View profile and source →</button></article>`).join('')}</div>`}
function deviceIcon(cat){return `<div class="device-icon" aria-hidden="true"><svg viewBox="0 0 90 50"><rect x="25" y="6" width="40" height="38" rx="${cat==='CGM'?19:8}" fill="white" stroke="#c1bddf" stroke-width="2"/><circle cx="45" cy="25" r="9" fill="#eeecfa"/><circle cx="45" cy="25" r="3" fill="#8d85ce"/></svg></div>`}
function catalog(){const list=products.filter(p=>(type==='all'||p.type.includes(type))&&(category==='all'||p.cat===category)&&(p.name+' '+p.brand).toLowerCase().includes(search.toLowerCase()));return head('Devices & products','Selected US devices and stated indications, not a market-share ranking.',types())+`<div class="product-tools"><input type="search" id="product-search" aria-label="Search products or manufacturers" placeholder="Search products or manufacturers" value="${esc(search)}"><div class="chips">${[['all','All devices'],['CGM','Glucose monitors'],['AID','Pumps / AID']].map(([id,label])=>`<button data-category="${id}" class="${category===id?'active':''}">${label}</button>`).join('')}</div></div><div class="product-grid">${list.map(p=>`<article class="product-card"><div class="product-top"><span class="pill purple">${p.cat}</span><small>${p.brand}</small></div>${deviceIcon(p.cat)}<h2>${p.name}</h2><p>${p.use}</p><div class="tags"><span class="tag">${p.access}</span><span class="tag">${p.wear}</span></div><p>${p.audience}</p><a href="${sources[p.source].url}" target="_blank" rel="noopener">Indication and documentation ↗</a><label><input type="checkbox" data-compare="${p.id}" ${selected.has(p.id)?'checked':''}> Compare product</label></article>`).join('')||'<div class="empty">No devices match this selection.</div>'}</div><p class="caption">Category illustrations, not product photographs. Specifications and indications are summarized; individual combinations have their own requirements. Not a treatment recommendation.</p>`}
function industry(){const c=companies.find(x=>x.id===company);return head('Companies','Who develops the devices and how their portfolios connect.')+`<div class="industry-layout"><div class="company-list">${companies.map(x=>`<button data-company="${x.id}" class="${company===x.id?'active':''}"><span class="company-initial">${x.name[0]}</span><span><strong>${x.name}</strong><small>${x.category}</small></span><b>→</b></button>`).join('')}</div><article class="panel"><div class="panelhead"><div><h2>${c.name}</h2><p>${c.category}</p></div></div><p class="big-note">${c.role}</p>${c.products.map(id=>{const p=products.find(x=>x.id===id);return `<button class="company-product" data-company-product="${id}"><span class="signal-icon">▣</span><span><strong>${p.name}</strong><small>${p.audience}</small></span><b>View product →</b></button>`}).join('')}<div class="company-signal"><small>Observed signal</small><p>${c.signal}</p>${source(c.source)}</div></article></div><div class="connect"><span>Company coverage currently focuses on selected device manufacturers. It is not a complete census of diabetes companies.</span>${link('industry/market','Explore market signals')}</div>`}
function market(){return head('Market signals','Adoption, revenue and expansion, with distinct populations and periods.')+`<div class="kpis">${kpi('Dexcom US revenue','$969.8 <small>m</small>','Q3 2026 · regional corporate revenue','dexrev')}${kpi('Prior-year US revenue','$851.9 <small>m</small>','Dexcom · Q3 2025','dexrev')}${kpi('CGM use · T2 with insulin','17.2<small>%</small>','Medicare Advantage · December 2023','adoption')}${kpi('Diagnosed diabetes burden','$412.9 <small>bn</small>','Economic cost · 2022 · not market size','cost')}</div><div class="grid-two">${panel('Expansion milestones',[['Aug 2024','Omnipod 5 expands to adults with type 2','omni'],['Mar 2025','Control-IQ+ launches for broader use','tandem'],['Aug 2025','MiniMed 780G indication expands to type 2','med'],['Jun 2026','Stelo OTC indication expands to children 2+ without insulin','stelo']].map(([date,text,id])=>`<div class="trend"><time>${date}</time><div><h3>${text}</h3>${source(id,'Source announcement or decision')}</div></div>`).join(''))}${adoption()}</div><p class="caption">Commercial figures are not user counts, prevalence or market-share estimates. This edition does not contain a complete market-size model.</p>`}
function audiencePage(group,page){if(group==='public')return page==='influencers'?influencers():questions('public');if(page==='profile')return group==='patients'?patientProfile():caregiverProfile();if(page==='personas')return personaPage(group);if(page==='journey')return journey(group);if(page==='routine')return routine(group);return questions(group)}
function render(){const raw=location.hash.slice(1)||'epidemiology';const aliases={overview:'epidemiology',people:'patients/profile',family:'caregivers/profile',journey:'patients/journey',personas:'patients/personas',life:'patients/routine',products:'industry/products',industry:'industry/companies',market:'industry/market',online:'public/online',influencers:'public/influencers'};route=aliases[raw]||raw;let [group,page]=route.split('/');if(!['epidemiology','healthcare',...Object.keys(groupTabs)].includes(group)){group='epidemiology';route=group}if(groupTabs[group]&&!groupTabs[group].some(t=>t[0]===page)){page=groupTabs[group][0][0];route=group+'/'+page}navigation(group);const labels={patients:'Patients',caregivers:'Caregivers',public:'General public',industry:'Industry & market'};let html=group==='epidemiology'?epidemiology():group==='healthcare'?healthcare():group==='industry'?(page==='companies'?industry():page==='products'?catalog():market()):audiencePage(group,page);if(groupTabs[group])html=`<p class="section-breadcrumb">${labels[group]}</p><nav class="section-tabs" aria-label="${labels[group]} sections">${groupTabs[group].map(([id,label])=>`<button data-go="${group}/${id}" class="${id===page?'active':''}" ${id===page?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`+html;$('main').innerHTML=html+'<footer><span>Perspective · US diabetes intelligence</span><span>Source periods vary · evidence, editorial curation and hypotheses are identified</span></footer>';bind();compareBar()}
function navigation(active){$('navigation').innerHTML=`<a href="#epidemiology" class="${active==='epidemiology'?'active':''}"><span>◫</span>Epidemiology</a><a href="#healthcare" class="${active==='healthcare'?'active':''}"><span>＋</span>Healthcare system</a>`+Object.entries({patients:'Patients',caregivers:'Caregivers',public:'General public',industry:'Industry & market'}).map(([id,label])=>`<div class="nav-section"><a href="#${id}/${groupTabs[id][0][0]}" class="${active===id?'active':''}"><span>${{patients:'◉',caregivers:'◎',public:'⌕',industry:'▥'}[id]}</span>${label}</a>${active===id?`<div class="nested-links">${groupTabs[id].map(([sub,name])=>`<a href="#${id}/${sub}" ${route===id+'/'+sub?'aria-current="page" class="selected"':''}>${name}</a>`).join('')}</div>`:''}</div>`).join('')}
function go(r){if(location.hash==='#'+r)render();else location.hash=r;window.scrollTo(0,0)}
function dialog(html){$('dialog-body').innerHTML=html;if(!$('dialog').open)$('dialog').showModal()}
function showSources(id){dialog(`<h2>${id?'Source and context':'Sources'}</h2>${(id?[[id,sources[id]]]:Object.entries(sources)).map(([key,s])=>`<article class="source-entry"><h3>${s.title}</h3><p>${s.note}</p><a href="${s.url}" target="_blank" rel="noopener">Open original source ↗</a></article>`).join('')}`)}
function creator(id){const c=creators.find(x=>x.id===id);dialog(`<div class="creator-mini"><div class="avatar">${c.initials}</div><div><h2>${c.name}</h2><p>${c.brand}</p></div></div><p>${c.profile}</p><p>${c.themes.join(' · ')}<br>${c.format}</p><p>Biography and positioning are based on public profiles. Followers, audience composition, engagement and commercial relationships have not been audited.</p><a href="${sources[c.source].url}" target="_blank" rel="noopener">Official profile ↗</a>`)}
function compareBar(){$('compare-bar').hidden=!selected.size;$('compare-bar').innerHTML=`<span>${selected.size} selected · maximum 3</span><button id="compare-now" ${selected.size<2?'disabled':''}>Compare →</button><button id="compare-clear" aria-label="Clear product comparison">×</button>`;$('compare-clear').onclick=()=>{selected.clear();render()};$('compare-now').onclick=()=>{const ps=products.filter(p=>selected.has(p.id));dialog(`<h2>Compare products</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>Feature</th>${ps.map(p=>`<th>${p.name}</th>`).join('')}</tr></thead><tbody>${[['Manufacturer','brand'],['Category','cat'],['Audience','audience'],['Access','access'],['Wear / system','wear'],['Role','use']].map(([label,key])=>`<tr><td>${label}</td>${ps.map(p=>`<td>${p[key]}</td>`).join('')}</tr>`).join('')}<tr><td>Documentation</td>${ps.map(p=>`<td><a href="${sources[p.source].url}" target="_blank" rel="noopener">Source ↗</a></td>`).join('')}</tr></tbody></table></div><p>CGM and AID have different roles. This comparison is not a recommendation of clinical suitability.</p>`)}}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>showSources(b.dataset.source));document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;render()});document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{selectedState=b.dataset.state;render()});document.querySelectorAll('[data-state-all]').forEach(b=>b.onclick=()=>{selectedState=null;render()});document.querySelectorAll('.map-state').forEach(p=>{p.onmousemove=e=>{const t=$('map-tooltip'),id=p.dataset.state,v=stateRates[id];if(!t)return;t.hidden=false;t.innerHTML=`<b>${stateNames[id]}</b><span>${v==null?'No 2023 data':v.toFixed(1)+'%'}</span>`;t.style.left=(e.offsetX+14)+'px';t.style.top=(e.offsetY+14)+'px'};p.onmouseleave=()=>{const t=$('map-tooltip');if(t)t.hidden=true};p.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectedState=p.dataset.state;render()}}});document.querySelectorAll('[data-epi-profile]').forEach(b=>b.onclick=()=>{epiProfile=b.dataset.epiProfile;render()});document.querySelectorAll('[data-epi-treatment]').forEach(b=>b.onclick=()=>{epiTreatment=b.dataset.epiTreatment;render()});document.querySelectorAll('[data-dimension]').forEach(b=>b.onclick=()=>{dimension=b.dataset.dimension;render()});document.querySelectorAll('[data-persona]').forEach(b=>b.onclick=()=>{persona=b.dataset.persona;go(personas.find(p=>p.id===persona).audience+'/personas')});document.querySelectorAll('[data-persona-select]').forEach(b=>b.onclick=()=>{persona=b.dataset.personaSelect;render()});document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{stage=Number(b.dataset.stage);render()});document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{theme=b.dataset.theme;render()});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{theme=b.dataset.topic;go(b.dataset.target)});document.querySelectorAll('[data-creator]').forEach(b=>b.onclick=()=>creator(b.dataset.creator));document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render()});document.querySelectorAll('[data-company]').forEach(b=>b.onclick=()=>{company=b.dataset.company;render()});document.querySelectorAll('[data-company-product]').forEach(b=>b.onclick=()=>{search=products.find(p=>p.id===b.dataset.companyProduct).name;type='all';category='all';go('industry/products')});document.querySelectorAll('[data-compare]').forEach(b=>b.onchange=()=>{if(b.checked&&selected.size===3){b.checked=false;dialog('<h2>Compare up to 3 products</h2><p>Remove a selected product before adding another.</p>');return}b.checked?selected.add(b.dataset.compare):selected.delete(b.dataset.compare);compareBar()});if($('product-search'))$('product-search').oninput=ev=>{search=ev.target.value;const pos=ev.target.selectionStart;render();$('product-search').focus();$('product-search').setSelectionRange(pos,pos)};if($('persona-journey'))$('persona-journey').onclick=()=>{const p=personas.find(x=>x.id===persona);stage=p.stage;go(p.audience+'/journey')}}
function exportData(){const rows=[['Category','Indicator','Value','Unit / interval','Population / period','Source']];for(const d of Object.values(demographics))for(const [label,v,ci]of d.rows)rows.push(['Epidemiology',d.label+' · '+label,v,'% ; 95% CI '+ci,d.scope,sources[d.source].url]);for(const p of products)rows.push(['Product',p.name,p.cat,p.access,p.audience,sources[p.source].url]);const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=u;a.download='perspective-us-diabetes.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.careDim){careDim=b.dataset.careDim;render()}if(b.dataset.insulinType){insulinType=b.dataset.insulinType;render()}if(b.dataset.insulinDim){insulinDim=b.dataset.insulinDim;render()}if(b.dataset.deviceView){deviceView=b.dataset.deviceView;render()}});$('sources').onclick=()=>showSources();$('close').onclick=()=>$('dialog').close();$('export').onclick=exportData;window.onhashchange=render;render();
